// AKV_005_FIVE_DOCS: rough cut generated by new_episode.py. It already renders: every line as word-synced kinetic
// type in the brand, light/dark worlds with a circle reveal (clips marked "world": "dark" in
// timeline.json), corner logo and end card. Then DESIGN IT: replace RoughScene per line with one
// literal subject (lib/icons.tsx), run the Focus Test on stills, and keep the scene map honest.
import React from "react";
import { AbsoluteFill, Audio, Sequence, staticFile, useCurrentFrame } from "remotion";
import TL from "./timeline.json";
import WORDS from "./words.json";
import { Backdrop, DarkWorld, Reveal, revealRadius } from "../../lib/stage";
import { Kinetic } from "../../lib/kinetic";
import { CornerBug, EndCard } from "../../lib/endcard";
import { WordEntry, fr, wordsApi } from "../../lib/time";
import { Timeline } from "../types";

const T = TL as unknown as Timeline;
const W = wordsApi(WORDS as WordEntry[]);
const last = T.clips[T.clips.length - 1];
const END_AT = Math.min(T.total - 2.5, last.at + (last.src[1] - last.src[0]) + 0.5);
export const AKV_005_FIVE_DOCS_FRAMES = fr(T.total);

const dark = T.clips.filter((c) => c.world === "dark");
const DARK_A = dark.length ? dark[0].at - 0.9 : -1;
const lastDark = dark[dark.length - 1];
const DARK_B = dark.length ? lastDark.at + (lastDark.src[1] - lastDark.src[0]) + 0.3 : -1;

const RoughScene: React.FC<{ i: number }> = ({ i }) => {
  const c = T.clips[i];
  const next = T.clips[i + 1];
  const start = c.at - 0.15;
  const end = next ? next.at - 0.15 : END_AT;
  const isDark = c.world === "dark";
  return (
    <Sequence from={fr(start)} durationInFrames={Math.max(1, fr(end) - fr(start))}>
      <Kinetic offset={start} lines={W.auto(c.id)} top={190} dark={isDark} />
      {/* DESIGN: one subject for this line goes here, e.g. <svg width={1080} height={1920}><Phone x={540} y={1150} /></svg> */}
    </Sequence>
  );
};

export const AKV_005_FIVE_DOCS: React.FC = () => {
  const f = useCurrentFrame();
  const r = dark.length ? revealRadius(f, fr(DARK_A), fr(DARK_A + 0.8), fr(DARK_B), fr(DARK_B + 0.7)) : 0;
  return (
    <AbsoluteFill>
      {T.audio !== false && <Audio src={staticFile(`episodes/${T.id}/mix.wav`)} />}
      <Backdrop />
      {T.clips.map((c, i) => (c.world !== "dark" ? <RoughScene key={c.id} i={i} /> : null))}
      {dark.length > 0 && (
        <Reveal r={r} cx={540} cy={1150}>
          <DarkWorld>{T.clips.map((c, i) => (c.world === "dark" ? <RoughScene key={c.id} i={i} /> : null))}</DarkWorld>
        </Reveal>
      )}
      {f > fr(T.clips[0].at + 2) && f < fr(END_AT) && <CornerBug dark={f > fr(DARK_A + 0.8) && f < fr(DARK_B)} />}
      <Sequence from={fr(END_AT)}><EndCard /></Sequence>
    </AbsoluteFill>
  );
};
